-- SOURCE: 20261021153336_directory_modal_integrity.sql
-- Modal directory CRUD: compact reads, atomic field patches and confirmed deletes.
-- Requires the existing directory/stock read and write migrations from package 8.
-- No new tables, policies, triggers, or privilege elevation.

-- Keep legacy catalog metadata and the original JSON/string representation.
-- The selected name key follows traffic_reference_name's existing precedence.
create or replace function public.traffic_directory_rename_reference(p_data jsonb,p_name text)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare document jsonb:=p_data; serialized boolean:=false; content text; field text;
begin
 if p_data is null or p_data='null'::jsonb then return to_jsonb(p_name);end if;
 if jsonb_typeof(document)='string' then
  content:=btrim(document#>>'{}');
  if left(content,1) not in ('{','[') then return to_jsonb(p_name);end if;
  begin document:=content::jsonb;exception when invalid_text_representation then return to_jsonb(p_name);end;
  serialized:=true;
 end if;
 if jsonb_typeof(document) is distinct from 'object' then raise exception 'Непідтримуваний формат назви довідника. Дані залишено без змін.';end if;
 foreach field in array array['Name','name','Назва','Текст','text','ПІБ'] loop
  if jsonb_typeof(document->field) in ('string','number') and nullif(btrim(document->>field),'') is not null then
   document:=jsonb_set(document,array[field],to_jsonb(p_name),false);
   return case when serialized then to_jsonb(document::text) else document end;
  end if;
 end loop;
 raise exception 'Не знайдено поле назви довідника. Дані залишено без змін.';
end $$;
revoke all on function public.traffic_directory_rename_reference(jsonb,text) from public;
grant execute on function public.traffic_directory_rename_reference(jsonb,text) to anon,authenticated;

create or replace function public.traffic_directory_write(p_kind text,p_id bigint,p_patch jsonb,p_expected jsonb default null)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare id_col text; allowed text[]; old jsonb; merged jsonb; name text; matches bigint[]; next_id bigint; value_type text; result jsonb; field text; payload text; name_expr text; affected bigint; plain boolean; original_data jsonb; renamed_data jsonb; outcome text:='updated';
begin
 id_col:=case p_kind when 'slyusars' then 'slyusar_id' when 'incomes' then 'income_id' when 'receivers' then 'receiver_id' when 'shops' then 'shop_id' when 'works' then 'work_id' when 'details' then 'detail_id' end;
 if id_col is null or jsonb_typeof(p_patch) is distinct from 'object' or (p_id is not null and p_id<=0) then raise exception 'Invalid directory patch';end if;
 plain:=p_kind in ('works','details');
 allowed:=case when plain then array['data'] when p_kind='slyusars' then array['Name','Пароль','Доступ','ПроцентРоботи','ПроцентЗапчастин','Склад'] else array['Name'] end;
 if exists(select 1 from jsonb_object_keys(p_patch) k where not k=any(allowed)) then raise exception 'Only directory metadata may change';end if;
 for field in select jsonb_object_keys(p_patch) loop
  if field in ('Name','data','Доступ','Пароль') and jsonb_typeof(p_patch->field) is distinct from 'string' then raise exception 'Некоректне текстове поле %',field;end if;
  if field in ('ПроцентРоботи','ПроцентЗапчастин','Склад') then
   if jsonb_typeof(p_patch->field) is distinct from 'number' then raise exception 'Некоректне числове поле %',field;end if;
   if (p_patch->>field)::numeric<0 or (field<>'Склад' and (p_patch->>field)::numeric>100) or (field='Склад' and trunc((p_patch->>field)::numeric)<>(p_patch->>field)::numeric) then raise exception 'Некоректне значення поля %',field;end if;
  end if;
 end loop;
 if p_kind in ('shops','details') then perform pg_advisory_xact_lock(1937010546,1);end if;
 perform pg_advisory_xact_lock(hashtext('traffic-directory:'||p_kind));
 if p_id is null then execute format('lock table public.%I in share row exclusive mode',p_kind);
 else
  if plain then
   execute format('select jsonb_build_object(''data'',public.traffic_reference_name(to_jsonb(data))),to_jsonb(data) from public.%I where %I=$1 for update',p_kind,id_col) into old,original_data using p_id;
  else execute format('select public.sto_read_object_v1(to_jsonb(data)) from public.%I where %I=$1 for update',p_kind,id_col) into old using p_id;end if;
  if old is null then raise exception 'Запис не знайдено або немає доступу. Оновіть список.';end if;
  if jsonb_typeof(p_expected) is distinct from 'object' then raise exception 'Directory baseline required';end if;
  if p_kind='slyusars' and p_id=1 then p_patch:=p_patch-'Name'-'Доступ';end if;
  for field in select jsonb_object_keys(p_patch) loop
   if old->field is distinct from p_expected->field and old->field is distinct from p_patch->field then raise exception 'Поле % змінено іншим користувачем. Оновіть дані.',field;end if;
  end loop;
 end if;
 merged:=coalesce(old,case when p_kind='slyusars' then '{"Опис":{},"Історія":{}}'::jsonb when p_kind='shops' then '{"Склад":{},"Історія":{},"Про магазин":""}'::jsonb else '{}'::jsonb end)||p_patch;
 field:=case when plain then 'data' else 'Name' end;
 name:=public.traffic_directory_name(merged->>field);if name='' then raise exception 'Назва обов’язкова';end if;
 name_expr:=case when plain then 'public.traffic_reference_name(to_jsonb(data))' else 'public.sto_read_object_v1(to_jsonb(data))->>''Name''' end;
 if p_id is null or name is distinct from public.traffic_directory_name(old->>field) then
  execute format('select array_agg(%I order by %I) from public.%I where public.traffic_directory_name(%s)=$1 and ($2 is null or %I<>$2)',id_col,id_col,p_kind,name_expr,id_col) into matches using name,p_id;
 end if;
 if coalesce(cardinality(matches),0)>1 then raise exception 'Неоднозначна назва: декілька історичних записів. Виберіть ID.';end if;
 if coalesce(cardinality(matches),0)=1 then
  if p_id is not null then raise exception 'Запис із такою назвою вже існує';end if;
  result:=public.traffic_directory_page(p_kind,'',0,false,matches[1]);return jsonb_build_object('status','existing','row',result->'items'->0);
 end if;
 if old is not null and merged=old then
  result:=public.traffic_directory_page(p_kind,'',0,false,p_id);return jsonb_build_object('status','unchanged','row',result->'items'->0);
 end if;
 select format_type(a.atttypid,a.atttypmod) into value_type from pg_attribute a where a.attrelid=format('public.%I',p_kind)::regclass and a.attname='data';
 if plain then
  renamed_data:=public.traffic_directory_rename_reference(original_data,merged->>'data');
  payload:=case when value_type in ('json','jsonb') or jsonb_typeof(renamed_data)<>'string' then renamed_data::text else renamed_data#>>'{}' end;
 else payload:=merged::text;end if;
 if p_id is null then
  execute format('select coalesce(max(%I),0)+1 from public.%I',id_col,p_kind) into next_id;
  execute format('insert into public.%I(%I,data) values($1,$2::%s)',p_kind,id_col,value_type) using next_id,payload;
  get diagnostics affected=row_count;p_id:=next_id;outcome:='created';
 else
  execute format('update public.%I set data=$1::%s where %I=$2',p_kind,value_type,id_col) using payload,p_id;
  get diagnostics affected=row_count;
 end if;
 if affected<>1 then raise exception 'База не підтвердила збереження. Перевірте доступ або оновіть запис.' using errcode='42501';end if;
 result:=public.traffic_directory_page(p_kind,'',0,false,p_id);
 if result->'items'->0 is null then raise exception 'Не отримано збережений запис';end if;
 return jsonb_build_object('status',outcome,'row',result->'items'->0);
end $$;

-- Legacy histories may be JSON objects, arrays, or JSON serialized inside strings.
create or replace function public.traffic_directory_has_history(v jsonb)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare child jsonb; parsed jsonb;
begin
 if v is null or v in ('null'::jsonb,'{}'::jsonb,'[]'::jsonb,'""'::jsonb) then return false;end if;
 if jsonb_typeof(v)='object' then
  for child in select value from jsonb_each(v) loop if public.traffic_directory_has_history(child) then return true;end if;end loop;return false;
 elsif jsonb_typeof(v)='array' then
  for child in select value from jsonb_array_elements(v) loop if public.traffic_directory_has_history(child) then return true;end if;end loop;return false;
 elsif jsonb_typeof(v)='string' then
  if btrim(v#>>'{}')='' then return false;end if;
  begin parsed:=(v#>>'{}')::jsonb;exception when others then return true;end;
  return public.traffic_directory_has_history(parsed);
 end if;
 return true;
end $$;
revoke all on function public.traffic_directory_has_history(jsonb) from public;
grant execute on function public.traffic_directory_has_history(jsonb) to anon,authenticated;

create or replace function public.traffic_directory_delete(p_kind text,p_id bigint,p_expected jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare id_col text; old jsonb; field text; affected bigint;
begin
 id_col:=case p_kind when 'slyusars' then 'slyusar_id' when 'incomes' then 'income_id' when 'receivers' then 'receiver_id' when 'shops' then 'shop_id' when 'works' then 'work_id' when 'details' then 'detail_id' when 'faktura' then 'faktura_id' end;
 if id_col is null or p_id is null or p_id<=0 or jsonb_typeof(p_expected) is distinct from 'object' or p_expected='{}'::jsonb then raise exception 'Виберіть запис для видалення зі списку.';end if;
 if p_kind='slyusars' and p_id=1 then raise exception 'Видалення адміністраторського акаунту заборонено!';end if;
 if p_kind in ('shops','details') then perform pg_advisory_xact_lock(1937010546,1);end if;
 perform pg_advisory_xact_lock(hashtext('traffic-directory:'||p_kind));
 if p_kind='faktura' then select to_jsonb(f) into old from public.faktura f where faktura_id=p_id for update;
 elsif p_kind in ('works','details') then execute format('select jsonb_build_object(''data'',public.traffic_reference_name(to_jsonb(data))) from public.%I where %I=$1 for update',p_kind,id_col) into old using p_id;
 else execute format('select public.sto_read_object_v1(to_jsonb(data)) from public.%I where %I=$1 for update',p_kind,id_col) into old using p_id;end if;
 if old is null then raise exception 'Запис уже видалено або немає доступу. Оновіть список.';end if;
 if (p_kind in ('works','details') and not (p_expected ? 'data')) or (p_kind not in ('works','details','faktura') and not (p_expected ? 'Name')) or (p_kind='faktura' and not (p_expected ? 'name')) then raise exception 'Немає вихідних даних запису. Виберіть його повторно.';end if;
 for field in select jsonb_object_keys(p_expected) loop
  if old->field is distinct from p_expected->field then raise exception 'Запис змінився після вибору. Оновіть його перед видаленням.';end if;
 end loop;
 if p_kind in ('slyusars','shops') and (public.traffic_directory_has_history(old->'Історія') or (p_kind='shops' and public.traffic_directory_has_history(old->'Склад'))) then
  raise exception 'Запис має історію або складські дані. Його видалення знищить ці дані та заблоковане.';
 end if;
 execute format('delete from public.%I where %I=$1',p_kind,id_col) using p_id;
 get diagnostics affected=row_count;
 if affected<>1 then raise exception 'База не підтвердила видалення. Перевірте права доступу.' using errcode='42501';end if;
 return jsonb_build_object('status','deleted','id',p_id);
end $$;

revoke all on function public.traffic_directory_page(text,text,integer,boolean,bigint),public.traffic_directory_write(text,bigint,jsonb,jsonb),public.traffic_directory_delete(text,bigint,jsonb) from public;
grant execute on function public.traffic_directory_page(text,text,integer,boolean,bigint),public.traffic_directory_write(text,bigint,jsonb,jsonb),public.traffic_directory_delete(text,bigint,jsonb) to anon,authenticated;

create or replace function public.traffic_contragent_write(p_id bigint,p_patch jsonb,p_expected jsonb default null)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare old jsonb; merged jsonb; iban text; n integer; next_id bigint; field text; result jsonb; affected bigint;
begin
 if jsonb_typeof(p_patch) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_patch) k where k not in ('name','oderjyvach','prumitka','data','namber')) then raise exception 'Invalid counterparty patch';end if;
 perform pg_advisory_xact_lock(hashtext('traffic-directory:faktura'));
 if p_id is null then lock table public.faktura in share row exclusive mode;
 else
  select to_jsonb(f) into old from public.faktura f where faktura_id=p_id for update;
  if old is null or p_expected is null then raise exception 'Оновіть контрагента перед редагуванням';end if;
  for field in select jsonb_object_keys(p_patch) loop
   if old->field is distinct from p_expected->field and old->field is distinct from p_patch->field then raise exception 'Контрагент змінений іншим користувачем. Оновіть дані.';end if;
  end loop;
 end if;
 merged:=coalesce(old,'{}'::jsonb)||p_patch;
 if old is not null and merged=old then return old;end if;
 if public.traffic_directory_name(merged->>'name')='' then raise exception 'Назва обов’язкова';end if;
 iban:=substring(regexp_replace(upper(coalesce(merged->>'prumitka','')),'[[:space:]]','','g') from 'UA[0-9]{27}');
 -- An entity can have several bank accounts. Compare IBAN when available;
 -- without one, compare the complete normalized name/recipient pair.
 select count(*) into n from public.faktura f where (p_id is null or f.faktura_id<>p_id) and
  case when iban is not null then substring(regexp_replace(upper(coalesce(f.prumitka,'')),'[[:space:]]','','g') from 'UA[0-9]{27}')=iban
   else public.traffic_directory_name(f.name)=public.traffic_directory_name(merged->>'name') and public.traffic_directory_name(f.oderjyvach)=public.traffic_directory_name(merged->>'oderjyvach') end;
 if n>0 and (p_id is null or public.traffic_directory_name(old->>'name') is distinct from public.traffic_directory_name(merged->>'name')
  or public.traffic_directory_name(old->>'oderjyvach') is distinct from public.traffic_directory_name(merged->>'oderjyvach')
  or substring(regexp_replace(upper(coalesce(old->>'prumitka','')),'[[:space:]]','','g') from 'UA[0-9]{27}') is distinct from iban)
 then raise exception 'Контрагент з такими реквізитами вже існує (% записів). Виберіть потрібний ID.',n;end if;
 if p_id is null then
  select coalesce(max(faktura_id),0)+1 into next_id from public.faktura;
  merged:=merged||jsonb_build_object('faktura_id',next_id);
  insert into public.faktura(faktura_id,name,oderjyvach,prumitka,data,namber)
   select f.faktura_id,f.name,f.oderjyvach,f.prumitka,f.data,f.namber from jsonb_populate_record(null::public.faktura,merged) f;
  get diagnostics affected=row_count;
  p_id:=next_id;
 else
  update public.faktura t set name=f.name,oderjyvach=f.oderjyvach,prumitka=f.prumitka,data=f.data,namber=f.namber from jsonb_populate_record(null::public.faktura,merged) f where t.faktura_id=p_id;
  get diagnostics affected=row_count;
 end if;
 if affected<>1 then raise exception 'База не підтвердила збереження контрагента. Перевірте доступ.' using errcode='42501';end if;
 select to_jsonb(f) into result from public.faktura f where faktura_id=p_id;
 if result is null then raise exception 'Не отримано збережений запис контрагента';end if;
 return result;
end $$;

revoke all on function public.traffic_contragent_write(bigint,jsonb,jsonb) from public;
grant execute on function public.traffic_contragent_write(bigint,jsonb,jsonb) to anon,authenticated;

-- Both reference fields in one confirmation either commit together or roll back.
create or replace function public.traffic_directory_reference_batch(p_changes jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare item jsonb; result jsonb:='[]'::jsonb; receipt jsonb; selected bigint;
begin
 if jsonb_typeof(p_changes) is distinct from 'array' then raise exception 'Invalid reference batch';end if;
 if jsonb_array_length(p_changes)>2 or exists(select 1 from jsonb_array_elements(p_changes) x where coalesce(x->>'kind','') not in ('shops','details') or coalesce(x->>'mode','') not in ('add','edit','delete'))
  or (select count(*)<>count(distinct x->>'kind') from jsonb_array_elements(p_changes) x) then raise exception 'Invalid reference batch';end if;
 perform pg_advisory_xact_lock(1937010546,1);
 for item in select value from jsonb_array_elements(p_changes) order by value->>'kind' loop
  selected:=nullif(item->>'id','')::bigint;
  if item->>'mode'='add' then
   if selected is not null then raise exception 'New reference must not replace a selected record';end if;
   receipt:=public.traffic_directory_write(item->>'kind',null,item->'patch',null);
  else
   if selected is null or selected<=0 then raise exception 'Selected reference required';end if;
   if item->>'mode'='edit' then receipt:=public.traffic_directory_write(item->>'kind',selected,item->'patch',item->'expected');
   else receipt:=public.traffic_directory_delete(item->>'kind',selected,item->'expected');end if;
  end if;
  result:=result||jsonb_build_array(jsonb_build_object('kind',item->>'kind')||receipt);
 end loop;
 return result;
end $$;
revoke all on function public.traffic_directory_reference_batch(jsonb) from public;
grant execute on function public.traffic_directory_reference_batch(jsonb) to anon,authenticated;

-- SOURCE: 20261023124514_traffic_work_directory_search.sql
-- Work suggestions: unordered words, partial words and common Ukrainian endings.
-- Exact directory lookup for CRUD keeps its literal normalized comparison.

create or replace function public.traffic_work_search_words(p_value text)
returns text[] language sql immutable security invoker set search_path=pg_catalog,public as $$
 select coalesce(array_agg(word order by ord),'{}'::text[])
 from regexp_split_to_table(public.traffic_directory_name(p_value),'[^0-9a-zа-яёіїєґ]+') with ordinality t(word,ord)
 where word<>'';
$$;

-- Keep this suffix list and minimum stem length in sync with directoryRead.ts.
-- This is a bounded ending fold, not a dictionary or an AI request.
create or replace function public.traffic_work_search_stem(p_word text)
returns text language sql immutable security invoker set search_path=pg_catalog as $$
 select case when p_word ~ '^[а-яёіїєґ]+$' and length(stem)>=3 then stem else p_word end
 from (select regexp_replace(p_word,'(ого|ому|ими|іми|ами|ями|ої|ій|ий|ім|их|іх|ою|ею|єю|ом|ем|ям|ах|ях|а|я|у|ю|і|и|е|о|є)$','') stem) s;
$$;

create or replace function public.traffic_work_search_matches(p_label text,p_words text[],p_stems text[])
returns boolean language sql immutable security invoker set search_path=pg_catalog,public as $$
 with words as materialized (
  select word,public.traffic_work_search_stem(word) stem
  from unnest(public.traffic_work_search_words(p_label)) t(word)
 )
 select not exists (
  select 1 from unnest(p_words,p_stems) q(word,stem)
  where not exists (select 1 from words d where strpos(d.word,q.word)=1 or d.stem=q.stem)
 );
$$;

create or replace function public.traffic_directory_page(p_kind text,p_query text default '',p_offset integer default 0,p_exact boolean default false,p_id bigint default null)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare id_col text; result jsonb; projection text; label text; search_predicate text;
 query_words text[]; query_stems text[];
begin
 id_col:=case p_kind when 'slyusars' then 'slyusar_id' when 'incomes' then 'income_id' when 'receivers' then 'receiver_id' when 'faktura' then 'faktura_id' when 'works' then 'work_id' when 'shops' then 'shop_id' when 'details' then 'detail_id' end;
 if id_col is null or p_offset is null or p_offset<0 or (p_id is not null and p_id<=0) then raise exception 'Invalid directory';end if;
 if p_kind='faktura' then
  projection:='jsonb_build_object(''faktura_id'',t.faktura_id,''name'',t.name,''oderjyvach'',t.oderjyvach,''prumitka'',t.prumitka,''data'',t.data,''namber'',t.namber)';
  label:='coalesce(t.oderjyvach,'''')';
 elsif p_kind in ('works','details') then
  projection:=format('jsonb_build_object(%L,t.%I,''data'',public.traffic_reference_name(to_jsonb(t.data)))',id_col,id_col);
  label:='coalesce(public.traffic_reference_name(to_jsonb(t.data)),'''')';
 else
  projection:=format('jsonb_build_object(%L,t.%I,''data'',(select coalesce(jsonb_object_agg(key,value),''{}''::jsonb) from jsonb_each(public.sto_read_object_v1(to_jsonb(t.data))) where key=any(%L::text[])))',id_col,id_col,
   case when p_kind='slyusars' then case when p_id is null then '{Name,Доступ}' else '{Name,Доступ,ПроцентРоботи,ПроцентЗапчастин,Склад,Пароль}' end else '{Name}' end);
  label:='coalesce(public.sto_read_object_v1(to_jsonb(t.data))->>''Name'','''')';
 end if;
 if p_kind='works' and not coalesce(p_exact,false) then
  -- Parse the query once, not once per candidate row. An empty query remains a
  -- directory read; punctuation alone must not turn into an unfiltered search.
  query_words:=public.traffic_work_search_words(p_query);
  select coalesce(array_agg(public.traffic_work_search_stem(word) order by ord),'{}'::text[])
   into query_stems from unnest(query_words) with ordinality t(word,ord);
  search_predicate:=case when cardinality(query_words)=0 and public.traffic_directory_name(p_query)<>'' then 'false'
   else format('public.traffic_work_search_matches(%s,$5,$6)',label) end;
 else
  search_predicate:=format('strpos(public.traffic_directory_name(%s),public.traffic_directory_name($1))>0',label);
 end if;
 execute format($query$
  with matches as materialized (
   select t.%I id,%s label from public.%I t
   where ($4 is null or t.%I=$4)
    and (case when $3 then public.traffic_directory_name(%s)=public.traffic_directory_name($1)
     else %s end)
  ), page as (select * from matches order by label,id offset $2 limit 50),
  serialized as (select p.id,p.label,%s row from page p join public.%I t on t.%I=p.id)
  select jsonb_build_object('items',coalesce((select jsonb_agg(row order by label,id) from serialized),'[]'::jsonb),
   'total',(select count(*) from matches))
 $query$,id_col,label,p_kind,id_col,label,search_predicate,projection,p_kind,id_col)
 into result using p_query,p_offset,p_exact,p_id,query_words,query_stems;
 return result;
end $$;

revoke all on function public.traffic_work_search_words(text),public.traffic_work_search_stem(text),public.traffic_work_search_matches(text,text[],text[]),public.traffic_directory_page(text,text,integer,boolean,bigint) from public;
grant execute on function public.traffic_work_search_words(text),public.traffic_work_search_stem(text),public.traffic_work_search_matches(text,text[],text[]),public.traffic_directory_page(text,text,integer,boolean,bigint) to anon,authenticated;
